  "ov.syncFailedDesc": { sv: "Synkroniseringen misslyckades. Din chatbot kanske inte har den senaste datan.", en: "Sync failed. Your chatbot might not have the latest data.", nl: "Synchronisatie mislukt. Uw chatbot heeft mogelijk niet de nieuwste gegevens.", de: "Synchronisierung fehlgeschlagen. Ihr Chatbot hat möglicherweise nicht die neuesten Daten.", fi: "Synkronointi epäonnistui. Chatbotillasi ei ehkä ole uusinta tietoa.", fr: "Échec de la synchronisation. Votre chatbot n'a peut-être pas les dernières données.", es: "Error de sincronización. Su chatbot podría no tener los datos más recientes.", it: "Sincronizzazione non riuscita. Il chatbot potrebbe non avere i dati più recenti.", da: "Synkronisering mislykkedes. Din chatbot har måske ikke de nyeste data.", no: "Synkronisering mislyktes. Chatboten din har kanskje ikke de nyeste dataene." },
