export function translate(lang: DashboardLang, key: string, vars?: Record<string, string>): string {
  const entry = DASHBOARD_DICT[key];
  if (!entry) return key;
  let out = entry[lang] || entry.en || key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      out = out.split(`{${k}}`).join(v);
    }
  }
  return out;
}

export function langLabel(lang: DashboardLang): string {
  const labels: Record<DashboardLang, string> = {
    sv: "Svenska", en: "English", nl: "Dutch", de: "German", fi: "Finnish",
    fr: "French", es: "Spanish", it: "Italian", da: "Danish", no: "Norwegian",
  };
  return labels[lang];
}

